import{c as t,Q as o,j as a,m as i}from"./chunks/framework.g_l1frA7.js";const m=JSON.parse('{"title":"Insights","description":"","frontmatter":{},"headers":[],"relativePath":"guide/insights.md","filePath":"guide/insights.md","lastUpdated":null}'),n={name:"guide/insights.md"};function s(r,e,l,h,d,g){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="insights" tabindex="-1">Insights <a class="header-anchor" href="#insights" aria-label="Permalink to &quot;Insights&quot;">​</a></h1><p>Insights surfaces what deserves your attention before it becomes a problem.</p><h2 id="tabs" tabindex="-1">Tabs <a class="header-anchor" href="#tabs" aria-label="Permalink to &quot;Tabs&quot;">​</a></h2><ul><li><strong>Anomalies</strong> — outlier spend per category, using rolling baseline + z-score in <code>finsight-core::anomaly</code>. A spike from a known one-off (e.g. annual insurance) is flagged as “explainable” when prior-year history matches.</li><li><strong>Patterns</strong> — spending type drift, subscription creep, and budget forecast variance. Source: <code>spending/baseline</code> and <code>forecast</code>.</li><li><strong>Memory</strong> — agent memory items the Copilot has stored (<code>repos/agent_memory</code>). Review and delete anything wrong.</li><li><strong>Needs Review</strong> — the actionable queue: uncategorized, low-confidence categorizations, possible transfers, possible splits.</li></ul><h2 id="agent-memory" tabindex="-1">Agent Memory <a class="header-anchor" href="#agent-memory" aria-label="Permalink to &quot;Agent Memory&quot;">​</a></h2><p>The Copilot can store small, reviewable memory items (e.g. “User prefers grocery budget at $600”). They are rows in your encrypted database, shown on Insights → Memory, and fed into the context only when relevant. Delete any you disagree with — the Copilot will not re-create it without evidence.</p><h2 id="working-the-queue" tabindex="-1">Working the queue <a class="header-anchor" href="#working-the-queue" aria-label="Permalink to &quot;Working the queue&quot;">​</a></h2><p>The fastest path through Insights:</p><ol><li>Clear <strong>Needs Review</strong> first — categorize, merge, or split. Each fix improves tomorrow’s baseline.</li><li>Read <strong>Anomalies</strong> next — decide if the spike is a one-off or a new normal.</li><li>Skim <strong>Patterns</strong> before month close — shift one envelope instead of re-budgeting everything.</li></ol><p>See also: <a href="/FinSight/developers/crates">Anomalies in code</a>, <a href="/FinSight/copilot/memory">Copilot → Memory</a>.</p>',10)])])}const p=t(n,[["render",s]]);export{m as __pageData,p as default};
